n = int(input())
vertices=[0,1,2]; edges=[(0,1),(1,0)] if n == 1 else [(0,1),(1,2)]
degree={v:0 for v in vertices}
for a,b in edges: degree[b]+=1
queue=[v for v in vertices if degree[v] == 0]; count=0
while queue:
 v=queue.pop(0); count+=1
 for a,b in edges:
  if a == v:
   degree[b]-=1
   if degree[b] == 0: queue.append(b)
print('ok')

